patched-6.12.113.gfx_v8_0_ring_test_ring:
static int gfx_v8_0_ring_test_ring(struct amdgpu_ring *ring)
{
	struct amdgpu_device *adev = ring->adev;
	uint32_t tmp = 0;
	u64 producer_start;
	unsigned i;
	int r;

	WREG32(mmSCRATCH_REG0, 0xCAFEDEAD);
	r = amdgpu_ring_alloc(ring, 3);
	if (r)
		return r;

	producer_start = ring->wptr;
	amdgpu_ring_write(ring, PACKET3(PACKET3_SET_UCONFIG_REG, 1));
	amdgpu_ring_write(ring, mmSCRATCH_REG0 - PACKET3_SET_UCONFIG_REG_START);
	amdgpu_ring_write(ring, 0xDEADBEEF);
	amdgpu_ring_commit(ring);

	for (i = 0; i < adev->usec_timeout; i++) {
		tmp = RREG32(mmSCRATCH_REG0);
		if (tmp == 0xDEADBEEF)
			break;
		udelay(1);
	}

	if (i >= adev->usec_timeout) {
		unsigned int j;

		dev_info(adev->dev, "GFX_PRODUCER gpu=%016llx start=%llu wptr=%llu doorbell=%u index=%u scratch=%08x\n",
			(unsigned long long)ring->gpu_addr,
			(unsigned long long)producer_start,
			(unsigned long long)ring->wptr,
			ring->use_doorbell, ring->doorbell_index, tmp);
		dev_info(adev->dev, "GFX_PRODUCER cntl=%08x rptr=%08x wptr=%08x cp_stat=%08x grbm=%08x\n",
			RREG32(mmCP_RB0_CNTL), RREG32(mmCP_RB0_RPTR),
			RREG32(mmCP_RB0_WPTR), RREG32(mmCP_STAT),
			RREG32(mmGRBM_STATUS));
		dev_info(adev->dev, "GFX_PRODUCER wb_rptr_native=%08x wb_rptr_le=%08x wb_wptr_native=%08x wb_wptr_le=%08x\n",
			*ring->rptr_cpu_addr,
			le32_to_cpu((__force __le32)*ring->rptr_cpu_addr),
			*ring->wptr_cpu_addr,
			le32_to_cpu((__force __le32)*ring->wptr_cpu_addr));
		for (j = 0; j < 3; j++) {
			u32 *word = &ring->ring[(producer_start + j) & ring->buf_mask];

			dev_info(adev->dev, "GFX_PRODUCER word%u native=%08x bytes=%4ph\n",
				j, *word, word);
		}
		if (adev->gart.ptr && ring->gpu_addr >= adev->gmc.gart_start &&
		    ring->gpu_addr <= adev->gmc.gart_end) {
			u64 page = (ring->gpu_addr - adev->gmc.gart_start) >> 12;
			void __iomem *pte = (void __iomem *)adev->gart.ptr + page * 8;

			dev_info(adev->dev, "GFX_PRODUCER gart_start=%016llx page=%llu pte_lo=%08x pte_hi=%08x\n",
				(unsigned long long)adev->gmc.gart_start,
				(unsigned long long)page, readl(pte), readl(pte + 4));
		}
		r = -ETIMEDOUT;
	}

	return r;
}

patched-6.12.113.gfx_v8_0_ring_test_ib:
static int gfx_v8_0_ring_test_ib(struct amdgpu_ring *ring, long timeout)
{
	struct amdgpu_device *adev = ring->adev;
	struct amdgpu_ib ib;
	struct dma_fence *f = NULL;

	unsigned int index;
	uint64_t gpu_addr;
	uint32_t tmp;
	long r;

	r = amdgpu_device_wb_get(adev, &index);
	if (r)
		return r;

	gpu_addr = adev->wb.gpu_addr + (index * 4);
	adev->wb.wb[index] = cpu_to_le32(0xCAFEDEAD);
	memset(&ib, 0, sizeof(ib));

	r = amdgpu_ib_get(adev, NULL, 20, AMDGPU_IB_POOL_DIRECT, &ib);
	if (r)
		goto err1;

	ib.ptr[0] = PACKET3(PACKET3_WRITE_DATA, 3);
	ib.ptr[1] = WRITE_DATA_DST_SEL(5) | WR_CONFIRM;
	ib.ptr[2] = lower_32_bits(gpu_addr);
	ib.ptr[3] = upper_32_bits(gpu_addr);
	ib.ptr[4] = 0xDEADBEEF;
	ib.length_dw = 5;

	r = amdgpu_ib_schedule(ring, 1, &ib, NULL, &f);
	if (r)
		goto err2;

	r = dma_fence_wait_timeout(f, false, timeout);
	if (r == 0) {
		r = -ETIMEDOUT;
		goto err2;
	} else if (r < 0) {
		goto err2;
	}

	tmp = adev->wb.wb[index];
	if (tmp == 0xDEADBEEF)
		r = 0;
	else
		r = -EINVAL;

err2:
	amdgpu_ib_free(adev, &ib, NULL);
	dma_fence_put(f);
err1:
	amdgpu_device_wb_free(adev, index);
	return r;
}

